// ─── File: RedisTopologyDemo.java ───
// Chooses Redis Sentinel vs Cluster by data characteristics, and shows
// the Cluster slot formula CRC16(key) % 16384 with hash tags.
import java.util.*;
import java.util.logging.*;

public class RedisTopologyDemo {
    private static final Logger log = Logger.getLogger("REDIS");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TopologyAdvisor advisor = new TopologyAdvisor(64, 100_000);

        Workload sessions = new Workload("auth-sessions", "sessions+otp", 8, 40_000);
        Workload pricing  = new Workload("pricing-cache", "dashboard-cache", 400, 500_000);

        log.info(() -> sessions.name() + " → " + advisor.recommend(sessions));
        log.info(() -> pricing.name()  + " → " + advisor.recommend(pricing));

        // Cluster slot routing for the pricing cache.
        SlotRouter router = new SlotRouter(16384);
        log.info("=== Cluster slot routing (CRC16(key) % 16384) ===");
        for (String key : List.of("session:SAV2001", "dashboard:CUR3001", "dashboard:SAV2001")) {
            int slot = router.slotFor(key);
            log.info(() -> "key=" + key + " → slot " + slot);
        }

        // Hash tags force related keys into the SAME slot for multi-key ops.
        log.info("=== Hash tags keep an account's keys in one slot ===");
        int s1 = router.slotFor("{SAV2001}:balance");
        int s2 = router.slotFor("{SAV2001}:limit");
        log.info(() -> "{SAV2001}:balance → slot " + s1 + " ; {SAV2001}:limit → slot " + s2
                + (s1 == s2 ? "  SAME slot → multi-key op allowed" : "  DIFFERENT → rejected"));
    }
}

