class Workload {
    private final String name, kind; private final int datasetGb, peakQps;
    Workload(String name, String kind, int datasetGb, int peakQps) {
        this.name = name; this.kind = kind; this.datasetGb = datasetGb; this.peakQps = peakQps;
    }
    String name() { return name; } String kind() { return kind; }
    int datasetGb() { return datasetGb; } int peakQps() { return peakQps; }
}

// ─── advisor/TopologyAdvisor.java ───
class TopologyAdvisor {
    private final int singleNodeMaxGb, singleNodeMaxQps;
    TopologyAdvisor(int singleNodeMaxGb, int singleNodeMaxQps) {
        this.singleNodeMaxGb = singleNodeMaxGb; this.singleNodeMaxQps = singleNodeMaxQps;
    }
    String recommend(Workload w) {
        boolean tooBig = w.datasetGb() > singleNodeMaxGb;
        boolean tooHot = w.peakQps() > singleNodeMaxQps;
        if (tooBig || tooHot) {
            return "CLUSTER (shard across 16384 slots; " + (tooBig ? "data > one node" : "")
                    + (tooBig && tooHot ? " & " : "") + (tooHot ? "QPS > one node" : "") + ")";
        }
        return "SENTINEL (fits one node; quorum failover; lightweight " + w.kind() + ")";
    }
}

// ─── cluster/SlotRouter.java ───
class SlotRouter {
    private final int slots;
    SlotRouter(int slots) { this.slots = slots; }
    // Redis Cluster: slot = CRC16(key) % 16384, hashing only the hash-tag if present.
    int slotFor(String key) {
        String hashPart = hashTag(key);
        return crc16(hashPart) % slots;
    }
    // Only the substring inside the FIRST {...} is hashed, if non-empty.
    private String hashTag(String key) {
        int open = key.indexOf('{');
        if (open >= 0) {
            int close = key.indexOf('}', open + 1);
            if (close > open + 1) return key.substring(open + 1, close);
        }
        return key;
    }
    // Standard CRC16-CCITT (same polynomial Redis uses).
    private int crc16(String s) {
        int crc = 0x0000;
        for (byte b : s.getBytes(java.nio.charset.StandardCharsets.UTF_8)) {
            crc ^= (b & 0xff) << 8;
            for (int i = 0; i < 8; i++) {
                crc = ((crc & 0x8000) != 0) ? (crc << 1) ^ 0x1021 : (crc << 1);
                crc &= 0xffff;
            }
        }
        return crc;
    }
}

